  "5 songs a day (≤ $0.40)": { es: "5 canciones al día (≤ $0.40)", ar: "5 أغانٍ يوميًا (≤ $0.40)", zh: "每天 5 首（≤ $0.40）", sw: "Nyimbo 5 kwa siku (≤ $0.40)", sv: "5 låtar per dag (≤ $0.40)" },
  "10 songs a day (≤ $0.80)": { es: "10 canciones al día (≤ $0.80)", ar: "10 أغانٍ يوميًا (≤ $0.80)", zh: "每天 10 首（≤ $0.80）", sw: "Nyimbo 10 kwa siku (≤ $0.80)", sv: "10 låtar per dag (≤ $0.80)" },
