  "Takes a few seconds. Free and unlimited. Tip: Ctrl + Enter also works.": { es: "Tarda unos segundos. Gratis e ilimitado. Consejo: Ctrl + Intro también funciona.", ar: "يستغرق بضع ثوانٍ. مجاني وبلا حدود. نصيحة: ‏Ctrl + Enter يعمل أيضًا.", zh: "只需几秒钟。免费且无限制。提示：也可以按 Ctrl + Enter。", sw: "Huchukua sekunde chache. Bure na bila kikomo. Kidokezo: Ctrl + Enter pia inafanya kazi.", sv: "Tar några sekunder. Gratis och obegränsat. Tips: Ctrl + Enter fungerar också." },
  "Your music will appear here": { es: "Tu música aparecerá aquí", ar: "ستظهر موسيقاك هنا", zh: "你的音乐将显示在这里", sw: "Muziki wako utaonekana hapa", sv: "Din musik visas här" },
  "Describe it, or just tap a quick idea on the left, then press": { es: "Descríbela, o simplemente toca una idea rápida a la izquierda, y luego pulsa", ar: "صِفها، أو اضغط فكرة سريعة على اليسار، ثم اضغط", zh: "描述它，或直接点按左侧的快速创意，然后点击", sw: "Ieleze, au gusa tu wazo la haraka upande wa kushoto, kisha bonyeza", sv: "Beskriv den, eller tryck bara på en snabb idé till vänster, och tryck sedan på" },
  "Make my music": { es: "Crear mi música", ar: "اصنع موسيقاي", zh: "生成我的音乐", sw: "Tengeneza muziki wangu", sv: "Gör min musik" },
